// AP World History: Modern: free-response questions (SAQ style), one per CED topic (Claude version only).
// Each topic: [stimulus, [[part prompt, rubric], ...]]. Every part is worth 1 point; Claude grades only against the rubric.
window.AP_FRQ = window.AP_FRQ || {};
AP_FRQ.wh = {
"1.1": ["Answer the following about East Asia, c. 1200–1450, including Song dynasty China.", [
  ["Identify one way the Song dynasty used Confucianism to strengthen the state.", "Earns the point for identifying a valid use: the civil service examination system based on Confucian texts; a Confucian-trained bureaucracy (scholar-gentry); Neo-Confucianism reinforcing loyalty and filial piety/social hierarchy."],
  ["Describe one economic development in Song China.", "Earns the point for describing a development such as Champa rice increasing agricultural output and population, the Grand Canal expanding internal trade, paper money/flying cash, iron and steel production, porcelain/silk production, or commercialization and urbanization."],
  ["Explain one way Chinese culture influenced neighboring states in East Asia.", "Earns the point for explaining a specific influence on Japan, Korea, or Vietnam: adoption of Confucianism, Buddhism, Chinese writing system, bureaucratic models, or the tributary system."]
]],
"1.2": ["Answer the following about Dar al-Islam, c. 1200–1450.", [
  ["Identify one new Islamic state or empire that emerged in this period.", "Earns the point for identifying a state such as the Seljuk Turks/Seljuk Sultanate, the Mamluk Sultanate of Egypt, the Delhi Sultanate, or the Ottomans (early), or the Mali empire as a Muslim state."],
  ["Describe one intellectual or cultural achievement of the Islamic world in this period.", "Earns the point for describing an achievement: House of Wisdom preserving and translating Greek texts, advances in mathematics (algebra), astronomy, medicine (Ibn Sina), or scholarship in cities like Baghdad, Cairo, Córdoba, or Timbuktu."],
  ["Explain one way Islam spread during this period.", "Earns the point for explaining spread through trade/merchants (e.g., Indian Ocean or trans-Saharan routes), Sufi missionaries, military expansion, or conversion of rulers."]
]],
"1.3": ["Answer the following about South and Southeast Asia, c. 1200–1450.", [
  ["Identify one state that developed in South or Southeast Asia in this period.", "Earns the point for identifying the Delhi Sultanate, Vijayanagara Empire, Majapahit, Srivijaya, Khmer Empire (Angkor), Rajput kingdoms, or Chola."],
  ["Describe one way Hinduism or Buddhism shaped society in the region.", "Earns the point for describing an effect: Angkor Wat as a religious/political center, Bhakti movement, Buddhist monasteries, caste system reinforcement, or rulers using religion to legitimize power."],
  ["Explain one way the Delhi Sultanate affected South Asia.", "Earns the point for explaining an effect: spreading Islam in northern India, tension/interaction with Hindu populations, Indo-Islamic architecture, creating the Urdu language, or resisting Mongol invasions."]
]],
"1.4": ["Answer the following about state building in the Americas, c. 1200–1450.", [
  ["Identify one method the Mexica (Aztec) used to maintain power.", "Earns the point for identifying the tribute system, military conquest, human sacrifice/religious legitimation, or alliances (Triple Alliance)."],
  ["Describe the Inca system of labor known as mit'a.", "Earns the point for describing it as a system requiring communities to provide labor to the state for projects such as roads, farming, or mining, as a form of taxation."],
  ["Explain one similarity or difference in how the Aztec and Inca governed their empires.", "Earns the point for explaining a valid similarity or difference: both used religion to legitimize rule; Aztecs relied on tribute from conquered city-states with local rulers left in place, while Incas used a more centralized bureaucracy, roads, and labor tax; Incas had quipu and a road system."]
]],
"1.5": ["Answer the following about state building in Africa, c. 1200–1450.", [
  ["Identify one African state that grew wealthy from trade in this period.", "Earns the point for identifying Mali, Great Zimbabwe, the Swahili city-states (Kilwa, Mombasa, etc.), Songhai (early), or Ethiopia (Aksum's successor)."],
  ["Describe the significance of Mansa Musa's hajj.", "Earns the point for describing that his pilgrimage to Mecca displayed Mali's wealth (gold), spread fame of Mali, strengthened ties with the Islamic world, and brought scholars/architects back to Timbuktu."],
  ["Explain how religion shaped the kingdom of Ethiopia.", "Earns the point for explaining that Ethiopia was a Christian kingdom; rulers used Christianity for legitimacy (e.g., rock-cut churches of Lalibela; Solomonic dynasty claims) and it distinguished Ethiopia from Muslim neighbors."]
]],
"1.6": ["Answer the following about Europe, c. 1200–1450.", [
  ["Identify one feature of feudalism in Europe.", "Earns the point for identifying lords granting land (fiefs) to vassals for military service, manorialism, serfdom, or decentralized political power."],
  ["Describe the role of the Catholic Church in medieval European society.", "Earns the point for describing the Church as a unifying institution with religious, political, and economic power: tithes, landownership, education, legitimizing monarchs, or the Crusades."],
  ["Explain one effect of the Black Death on European society.", "Earns the point for explaining a consequence: labor shortage leading to higher wages and weakening of serfdom, questioning of the Church, peasant revolts, or economic disruption."]
]],
"1.7": ["Answer the following comparison question about c. 1200–1450.", [
  ["Identify one similarity in how states in two different regions legitimized their rule.", "Earns the point for identifying a similarity with specific examples, e.g., both Song China (Confucianism) and Delhi Sultanate (Islam) used religion/ideology; both Aztec and Inca used religious rituals; European monarchs used divine right/Church support."],
  ["Describe one difference in how two states in different regions were governed.", "Earns the point for describing a specific difference, e.g., Song China had a centralized bureaucracy chosen by exams while European states were decentralized under feudalism."],
  ["Explain one reason for the difference identified in part B.", "Earns the point for explaining a reason tied to the difference, e.g., China's long tradition of centralized imperial rule and Confucian ideology vs. Europe's fragmentation after Rome's fall."]
]],
"2.1": ["Answer the following about the Silk Roads, c. 1200–1450.", [
  ["Identify one luxury good traded along the Silk Roads.", "Earns the point for identifying silk, porcelain, spices, gems, horses, or other luxury goods."],
  ["Describe one innovation that facilitated trade along the Silk Roads.", "Earns the point for describing caravanserai, paper money/flying cash, bills of exchange, banking houses, or saddles/camel caravans."],
  ["Explain how the growth of trade led to the growth of cities along the Silk Roads.", "Earns the point for explaining that trade hubs like Samarkand or Kashgar grew as merchants stopped to trade, rest, and resupply, creating wealth and markets."]
]],
"2.2": ["Answer the following about the Mongol Empire.", [
  ["Identify one way the Mongols facilitated trade across Eurasia.", "Earns the point for identifying Pax Mongolica (peace/security on trade routes), the yam relay system, protection of merchants, or reduced tariffs."],
  ["Describe one example of cultural or technological transfer under the Mongols.", "Earns the point for describing a transfer such as gunpowder/printing to the west, Persian astronomy to China, Chinese medicine westward, or the movement of scholars, artisans, and religions."],
  ["Explain one negative consequence of Mongol expansion.", "Earns the point for explaining a consequence: destruction of cities (e.g., Baghdad 1258), mass deaths, or spread of the bubonic plague along trade routes."]
]],
"2.3": ["Answer the following about the Indian Ocean trade network, c. 1200–1450.", [
  ["Identify one technology that facilitated Indian Ocean trade.", "Earns the point for identifying the lateen sail, dhow, junk, astrolabe, magnetic compass, or knowledge of monsoon winds."],
  ["Describe how monsoon winds affected Indian Ocean trade.", "Earns the point for describing that seasonal wind patterns allowed predictable travel in one direction and back later in the year, shaping timing of voyages."],
  ["Explain one effect of Indian Ocean trade on East Africa.", "Earns the point for explaining the growth of Swahili city-states, spread of Islam, the Swahili language (Bantu/Arabic blend), or wealth from trade."]
]],
"2.4": ["Answer the following about the trans-Saharan trade routes.", [
  ["Identify one innovation that helped merchants cross the Sahara.", "Earns the point for identifying the camel, camel saddle, or camel caravans."],
  ["Describe the main goods exchanged on trans-Saharan routes.", "Earns the point for describing gold (from West Africa) exchanged for salt (from the Sahara/North Africa); also slaves, textiles, or horses."],
  ["Explain how trans-Saharan trade contributed to the growth of Mali.", "Earns the point for explaining that Mali taxed and controlled the gold-salt trade, becoming wealthy and powerful, and cities like Timbuktu became trade and learning centers."]
]],
"2.5": ["Answer the following about cultural consequences of connectivity, c. 1200–1450.", [
  ["Identify one traveler who recorded observations of different societies in this period.", "Earns the point for identifying Ibn Battuta, Marco Polo, Margery Kempe, Rabban Sauma, or Zheng He."],
  ["Describe one way religion spread through trade networks.", "Earns the point for describing Islam spreading to Southeast Asia/East Africa via merchants, Buddhism along the Silk Roads, or missionaries traveling with traders."],
  ["Explain one example of cultural syncretism resulting from connectivity.", "Earns the point for explaining a blending such as Swahili language/culture, Buddhism adapted in China (Chan/Zen), Islam blending with local beliefs in Southeast Asia or West Africa."]
]],
"2.6": ["Answer the following about environmental consequences of connectivity, c. 1200–1450.", [
  ["Identify one crop that spread through trade networks.", "Earns the point for identifying Champa rice, bananas, citrus, sugarcane, cotton, or other valid crop diffusion."],
  ["Describe how the bubonic plague spread across Afro-Eurasia.", "Earns the point for describing that fleas on rats traveled with merchants and armies along Silk Roads and sea routes, carrying the disease from Asia to the Middle East and Europe."],
  ["Explain one effect of the spread of a new crop on a society.", "Earns the point for explaining that a crop (e.g., Champa rice in China, bananas in Africa) increased food supply, supporting population growth or urbanization."]
]],
"2.7": ["Answer the following comparison question about trade networks, c. 1200–1450.", [
  ["Identify one similarity between the Silk Roads and the Indian Ocean trade network.", "Earns the point for identifying a similarity: both spread religions, both exchanged luxury goods, both led to growth of trading cities, both spread disease or technologies."],
  ["Describe one difference between the Silk Roads and the Indian Ocean trade.", "Earns the point for describing a difference: Silk Roads were overland and carried mostly luxury goods; Indian Ocean trade was maritime, carried larger volumes of bulk goods, and depended on monsoon winds."],
  ["Explain why Indian Ocean trade was able to carry more goods than the Silk Roads.", "Earns the point for explaining that ships could carry much larger cargoes more cheaply than camels, and monsoon navigation made trips predictable."]
]],
"3.1": ["Answer the following about land-based empires, c. 1450–1750.", [
  ["Identify one land-based empire that expanded during this period.", "Earns the point for identifying the Ottoman, Safavid, Mughal, Qing, or Russian Empire (or Manchu)."],
  ["Describe the role of gunpowder weapons in the expansion of land-based empires.", "Earns the point for describing that cannons and firearms helped empires defeat rivals and capture fortified cities (e.g., Ottoman conquest of Constantinople in 1453)."],
  ["Explain one challenge land-based empires faced in maintaining large territories.", "Earns the point for explaining a challenge: managing diverse populations, rebellions, cost of armies, succession disputes, or external threats."]
]],
"3.2": ["Answer the following about empire administration, c. 1450–1750.", [
  ["Identify one method a land-based empire used to collect revenue.", "Earns the point for identifying tax farming (Ottoman), zamindar tax collection (Mughal), tribute systems, or land taxes."],
  ["Describe the Ottoman devshirme system.", "Earns the point for describing the practice of taking Christian boys from the Balkans, converting them to Islam, and training them as soldiers (Janissaries) or administrators loyal to the sultan."],
  ["Explain one way rulers used monumental architecture or art to legitimize their power.", "Earns the point for explaining an example: Taj Mahal (Mughal), Versailles (Louis XIV), Süleymaniye Mosque (Ottoman), Forbidden City additions (Qing), showing wealth and power."]
]],
"3.3": ["Answer the following about belief systems in land-based empires, c. 1450–1750.", [
  ["Identify the religious split between the Ottoman and Safavid Empires.", "Earns the point for identifying Sunni (Ottoman) vs. Shi'a (Safavid) Islam."],
  ["Describe one effect of the Protestant Reformation on Europe.", "Earns the point for describing an effect: the split of Western Christianity, religious wars (Thirty Years' War), weakening of papal authority, Catholic Counter-Reformation."],
  ["Explain one way Akbar approached religious diversity in the Mughal Empire.", "Earns the point for explaining religious tolerance: abolishing the jizya tax on non-Muslims, Din-i Ilahi (blending religions), including Hindus in government, or interfaith debates."]
]],
"3.4": ["Answer the following comparison question about land-based empires, c. 1450–1750.", [
  ["Identify one similarity in how two land-based empires expanded.", "Earns the point for identifying a similarity with examples, e.g., the Ottomans and Mughals both used gunpowder weapons; both Qing and Russia expanded into Central Asia."],
  ["Describe one difference in how two land-based empires treated religious minorities.", "Earns the point for describing a difference, e.g., the Ottoman millet system allowed religious communities self-governance, while the Safavids enforced Shi'ism."],
  ["Explain one reason the empires in part B differed.", "Earns the point for explaining a reason connected to the difference, e.g., rulers' political need to unify a diverse population vs. using religion to distinguish the state from rivals."]
]],
"4.1": ["Answer the following about technological innovations, c. 1450–1750.", [
  ["Identify one technology that aided European maritime exploration.", "Earns the point for identifying the caravel, carrack, astrolabe, magnetic compass, lateen sail, or improved cartography."],
  ["Describe how one maritime technology originated outside Europe.", "Earns the point for describing that the magnetic compass came from China, the astrolabe was improved by Islamic scholars, or the lateen sail came from the Indian Ocean/Arab sailors."],
  ["Explain how new maritime technologies changed global trade.", "Earns the point for explaining that ships could cross oceans, linking the Americas to Afro-Eurasia and creating the first truly global trade networks."]
]],
"4.2": ["Answer the following about exploration, c. 1450–1750.", [
  ["Identify one motive for European exploration.", "Earns the point for identifying desire for gold/wealth, access to Asian spices, spreading Christianity, national glory, or bypassing Ottoman/Venetian control of trade."],
  ["Describe the role of Portugal in early exploration.", "Earns the point for describing that Portugal, supported by Prince Henry, explored the West African coast and found a sea route around Africa to India (Vasco da Gama), establishing trading posts."],
  ["Explain the significance of Columbus's voyages.", "Earns the point for explaining that they led to permanent contact between the Americas and Afro-Eurasia, beginning the Columbian Exchange and Spanish colonization."]
]],
"4.3": ["Answer the following about the Columbian Exchange.", [
  ["Identify one crop that moved from the Americas to Afro-Eurasia.", "Earns the point for identifying potatoes, maize (corn), cassava, tomatoes, tobacco, or cacao."],
  ["Describe one effect of European diseases on Indigenous American populations.", "Earns the point for describing massive population decline (up to 90% in some areas) from smallpox, measles, or other diseases."],
  ["Explain one effect of American food crops on Afro-Eurasian populations.", "Earns the point for explaining that high-calorie crops like potatoes and maize increased food supply and supported population growth in Europe, Africa, or China."]
]],
"4.4": ["Answer the following about the establishment of maritime empires, c. 1450–1750.", [
  ["Identify one European state that established a maritime empire.", "Earns the point for identifying Portugal, Spain, the Netherlands, Britain, or France."],
  ["Describe the role of joint-stock companies in European expansion.", "Earns the point for describing that companies like the Dutch or British East India Company pooled investors' money to fund voyages and colonies, reducing individual risk."],
  ["Explain one reason for the growth of the Atlantic slave trade.", "Earns the point for explaining the demand for labor on sugar or other plantations after Indigenous populations declined from disease."]
]],
"4.5": ["Answer the following about maintaining maritime empires, c. 1450–1750.", [
  ["Identify one labor system used in the Spanish colonies.", "Earns the point for identifying the encomienda, hacienda, or Spanish version of mit'a, or chattel slavery."],
  ["Describe how the Spanish mita system differed from the Inca mit'a.", "Earns the point for describing that the Spanish used it to force Indigenous people to work in silver mines (e.g., Potosí) under harsh conditions for Spanish profit, rather than for community/state projects."],
  ["Explain one way silver from the Americas affected the global economy.", "Earns the point for explaining that American silver flowed to China (which required silver for taxes), connecting global trade, or causing inflation in Spain/Europe."]
]],
"4.6": ["Answer the following about challenges to state power, c. 1450–1750.", [
  ["Identify one revolt against state power in this period.", "Earns the point for identifying the Fronde, Pueblo Revolt, Maratha resistance, Queen Nzinga's resistance, the Cossack revolts, or other valid example."],
  ["Describe the Pueblo Revolt.", "Earns the point for describing that in 1680 the Pueblo people in New Mexico rose against Spanish colonizers over religious persecution and forced labor, expelling them for about 12 years."],
  ["Explain one reason local groups resisted state expansion.", "Earns the point for explaining a reason: resisting taxes, forced labor, religious conversion, or loss of land and autonomy."]
]],
"4.7": ["Answer the following about changing social hierarchies, c. 1450–1750.", [
  ["Identify the casta system in Spanish America.", "Earns the point for identifying it as a racial hierarchy with peninsulares at the top, then creoles, mestizos, mulattoes, Indigenous people, and enslaved Africans."],
  ["Describe the position of peninsulares in the casta system.", "Earns the point for describing that peninsulares (Spanish-born) held the highest government and church positions."],
  ["Explain one way the casta system affected colonial society.", "Earns the point for explaining that it restricted opportunities by race/birth, created resentment among creoles, and reinforced European dominance."]
]],
"4.8": ["Answer the following about continuity and change, c. 1450–1750.", [
  ["Identify one continuity in global trade from 1450 to 1750.", "Earns the point for identifying a continuity: Indian Ocean trade remained important; China remained a major producer of manufactured goods; Silk Road trade continued; luxury goods still traded."],
  ["Describe one major change in global trade from 1450 to 1750.", "Earns the point for describing a change: connection of the Americas (global trade network), rise of European maritime empires, the Atlantic slave trade, joint-stock companies."],
  ["Explain one cause of the change described in part B.", "Earns the point for explaining a cause tied to that change: new maritime technologies, European demand for Asian goods, American silver, or demand for plantation labor."]
]],
"5.1": ["Answer the following about the Enlightenment.", [
  ["Identify one Enlightenment thinker and one idea associated with him or her.", "Earns the point for a correctly matched pair, e.g., Locke—natural rights (life, liberty, property); Rousseau—social contract/general will; Montesquieu—separation of powers; Voltaire—freedom of religion/speech; Wollstonecraft—women's rights."],
  ["Describe how Enlightenment ideas challenged absolute monarchy.", "Earns the point for describing that ideas of natural rights, popular sovereignty, and the social contract argued that government derives its power from the people, not divine right."],
  ["Explain one way Enlightenment ideas influenced a revolution.", "Earns the point for explaining a specific link: Declaration of Independence reflecting Locke; French Declaration of the Rights of Man; Haitian Revolution using liberty and equality; Latin American independence."]
]],
"5.2": ["Answer the following about nationalism and revolutions, 1750–1900.", [
  ["Identify one revolution in the Atlantic world between 1750 and 1900.", "Earns the point for identifying the American, French, Haitian, or a Latin American revolution (e.g., Bolívar's campaigns, Mexican independence)."],
  ["Describe one cause of the Haitian Revolution.", "Earns the point for describing brutal slavery on sugar plantations, inspiration from French Revolution ideals, or the large enslaved population versus a small white elite."],
  ["Explain how nationalism contributed to the unification of Germany or Italy.", "Earns the point for explaining that shared language, culture, and identity motivated leaders (Bismarck, Cavour, Garibaldi) to unify fragmented states into one nation."]
]],
"5.3": ["Answer the following about the start of the Industrial Revolution.", [
  ["Identify one factor that helped industrialization begin in Great Britain.", "Earns the point for identifying coal/iron deposits, rivers/canals, capital from trade, colonies, agricultural improvements freeing labor, or stable banking."],
  ["Describe how the steam engine changed production.", "Earns the point for describing that steam power allowed factories to be located anywhere, powered machinery, and increased production; it also powered trains and ships."],
  ["Explain how the enclosure movement contributed to industrialization.", "Earns the point for explaining that enclosure pushed rural people off common lands, providing workers for factories in cities."]
]],
"5.4": ["Answer the following about the spread of industrialization, 1750–1900.", [
  ["Identify one region outside Britain that industrialized by 1900.", "Earns the point for identifying Western Europe (Belgium, France, Germany), the United States, Russia, or Japan."],
  ["Describe how Japan industrialized during the Meiji Restoration.", "Earns the point for describing government-led reform: sending students abroad, building railroads and factories, and adopting Western technologies."],
  ["Explain one effect of industrialization on regions that did not industrialize (e.g., India or Egypt).", "Earns the point for explaining deindustrialization of local textile production, becoming suppliers of raw materials (cotton), or economic dependence on industrial nations."]
]],
"5.5": ["Answer the following about technology of the industrial age.", [
  ["Identify one industrial-age innovation in transportation.", "Earns the point for identifying the railroad, steamship, or the Suez Canal."],
  ["Describe one innovation in communication.", "Earns the point for describing the telegraph (or telephone) allowing near-instant long-distance messages."],
  ["Explain how new technologies of the second industrial revolution affected production.", "Earns the point for explaining that electricity, steel (Bessemer process), and chemicals increased the scale, efficiency, and variety of production."]
]],
"5.6": ["Answer the following about industrialization and the role of government, 1750–1900.", [
  ["Identify one state that promoted industrialization through government action.", "Earns the point for identifying Meiji Japan, Russia (Witte), Egypt (Muhammad Ali), or Germany."],
  ["Describe Muhammad Ali's efforts to industrialize Egypt.", "Earns the point for describing state-led development: building textile factories, military modernization, cotton production for export, and state control of industry."],
  ["Explain one reason some governments resisted industrialization.", "Earns the point for explaining a reason: fear of losing traditional elite power, cultural conservatism, or lack of capital—e.g., Qing officials resisting Western technology."]
]],
"5.7": ["Answer the following about economic developments in the industrial age.", [
  ["Identify one economic idea associated with Adam Smith.", "Earns the point for identifying laissez-faire capitalism, free markets, the invisible hand, or opposition to mercantilism."],
  ["Describe the role of transnational businesses in the industrial age.", "Earns the point for describing companies like HSBC or the United Fruit Company operating in multiple countries, controlling trade and resources."],
  ["Explain how new financial institutions supported industrial growth.", "Earns the point for explaining that stock markets, banks, and limited-liability corporations raised capital for factories, railroads, and expansion."]
]],
"5.8": ["Answer the following about reactions to the industrial economy, 1750–1900.", [
  ["Identify one group that formed to improve working conditions.", "Earns the point for identifying labor unions or socialist/communist organizations."],
  ["Describe the ideas of Karl Marx.", "Earns the point for describing that Marx argued the proletariat (workers) were exploited by the bourgeoisie (owners) and would overthrow capitalism in a class struggle, leading to a classless society."],
  ["Explain one reform that governments adopted in response to industrial problems.", "Earns the point for explaining a reform: child labor laws, limiting working hours, public education, expanded voting rights, or factory safety regulations."]
]],
"5.9": ["Answer the following about society in the industrial age.", [
  ["Identify one new social class that grew during industrialization.", "Earns the point for identifying the middle class (bourgeoisie) or the industrial working class (proletariat)."],
  ["Describe working conditions in early factories.", "Earns the point for describing long hours, low wages, child labor, dangerous machines, or unsanitary conditions."],
  ["Explain how industrialization affected gender roles.", "Earns the point for explaining a change: separation of home and work, the 'cult of domesticity' for middle-class women, or working-class women and children in factories."]
]],
"5.10": ["Answer the following about continuity and change in the industrial age.", [
  ["Identify one change in global production caused by industrialization.", "Earns the point for identifying a change: shift from hand production to machine production; factory system; mass production."],
  ["Describe one continuity in labor systems from before 1750 to 1900.", "Earns the point for describing a continuity: agricultural labor remained dominant in many regions, coerced labor/indentured servitude continued, or women remained in lower-paid work."],
  ["Explain one effect of industrialization on the global balance of power.", "Earns the point for explaining that industrialized nations gained military and economic power, enabling imperialism over non-industrialized regions."]
]],
"6.1": ["Answer the following about rationales for imperialism, 1750–1900.", [
  ["Identify one ideology used to justify imperialism.", "Earns the point for identifying Social Darwinism, the civilizing mission, 'White Man's Burden', religious conversion, or nationalism."],
  ["Describe how Social Darwinism was used to justify imperialism.", "Earns the point for describing that it misapplied 'survival of the fittest' to claim some races or nations were superior and entitled to rule others."],
  ["Explain one economic motive for imperialism.", "Earns the point for explaining that industrial nations wanted raw materials (rubber, cotton, palm oil) and new markets for manufactured goods."]
]],
"6.2": ["Answer the following about state expansion, 1750–1900.", [
  ["Identify one region colonized by European powers in the 1800s.", "Earns the point for identifying Africa (e.g., after the Berlin Conference), India, Southeast Asia, or Pacific islands."],
  ["Describe the significance of the Berlin Conference (1884–1885).", "Earns the point for describing that European powers divided Africa among themselves without African input, setting rules for claiming territory."],
  ["Explain one way Japan expanded its territory in this period.", "Earns the point for explaining the Sino-Japanese War (gaining Taiwan), the Russo-Japanese War, or annexation of Korea (1910)."]
]],
"6.3": ["Answer the following about Indigenous responses to state expansion, 1750–1900.", [
  ["Identify one resistance movement against imperialism.", "Earns the point for identifying the Indian Rebellion of 1857 (Sepoy Mutiny), Xhosa Cattle-Killing, Ghost Dance, Zulu resistance, Taiping Rebellion, Boxer Rebellion, Ethiopia's resistance (Adwa), or Samori Touré."],
  ["Describe the causes of the Indian Rebellion of 1857.", "Earns the point for describing that sepoys objected to rifle cartridges greased with animal fat offensive to Hindus and Muslims, as well as resentment of British rule and policies."],
  ["Explain one way Ethiopia remained independent.", "Earns the point for explaining that Menelik II modernized the army with firearms and defeated Italy at the Battle of Adwa (1896)."]
]],
"6.4": ["Answer the following about global economic development, 1750–1900.", [
  ["Identify one export economy that developed in a colonized region.", "Earns the point for identifying rubber (Congo, Amazon), cotton (Egypt, India), palm oil (West Africa), guano (Peru), sugar, or beef (Argentina)."],
  ["Describe how industrial demand shaped export economies.", "Earns the point for describing that factories in industrialized countries needed raw materials, so colonies specialized in producing one or a few cash crops or resources for export."],
  ["Explain one negative effect of export economies on colonized regions.", "Earns the point for explaining a harm: dependence on one product, vulnerability to price changes, food shortages, forced labor, or environmental damage."]
]],
"6.5": ["Answer the following about economic imperialism, 1750–1900.", [
  ["Identify one example of economic imperialism.", "Earns the point for identifying the Opium Wars/British influence in China, spheres of influence in China, U.S. or British investment in Latin America (e.g., United Fruit Company), or the Open Door Policy."],
  ["Describe the causes of the Opium Wars.", "Earns the point for describing that Britain sold opium to China to balance trade; China tried to stop it, and Britain went to war to protect its trade."],
  ["Explain one effect of the Treaty of Nanjing on China.", "Earns the point for explaining that China lost Hong Kong, opened treaty ports, paid indemnities, and granted extraterritoriality, weakening its sovereignty."]
]],
"6.6": ["Answer the following about migration, 1750–1900.", [
  ["Identify one cause of migration in the 1800s.", "Earns the point for identifying famine (Irish Potato Famine), industrial jobs, cheap transportation (steamships, railroads), political persecution, or labor demand."],
  ["Describe indentured servitude in the 1800s.", "Earns the point for describing workers (e.g., from India or China) who signed contracts to work for a set number of years in exchange for passage to places like the Caribbean, South Africa, or Fiji."],
  ["Explain why many migrants in this period were men.", "Earns the point for explaining that jobs in mines, railroads, and plantations recruited men for manual labor; many intended to send money home and return."]
]],
"6.7": ["Answer the following about the effects of migration, 1750–1900.", [
  ["Identify one ethnic enclave formed by migrants in this period.", "Earns the point for identifying Chinatowns in the U.S., Indian communities in East Africa or the Caribbean, Italian communities in Argentina, or others."],
  ["Describe one example of anti-immigrant legislation.", "Earns the point for describing the Chinese Exclusion Act (1882) or the White Australia Policy."],
  ["Explain one way migration changed the societies migrants moved to.", "Earns the point for explaining cultural blending (food, religion, language), growth of cities, or increased labor supply for industry and agriculture."]
]],
"6.8": ["Answer the following causation question about the imperial age.", [
  ["Identify one cause of imperialism in the 1800s.", "Earns the point for identifying industrialization's need for raw materials and markets, nationalism, ideologies like Social Darwinism, or military technology (steamships, rifles, quinine)."],
  ["Describe one technological factor that allowed European imperial expansion.", "Earns the point for describing steamships (moving upriver), the Maxim gun, breech-loading rifles, quinine against malaria, or telegraphs."],
  ["Explain one long-term effect of imperialism on colonized societies.", "Earns the point for explaining arbitrary borders, economic dependence, loss of Indigenous institutions, spread of European languages/religions, or seeds of nationalist movements."]
]],
"7.1": ["Answer the following about shifting power after 1900.", [
  ["Identify one empire that collapsed in the early twentieth century.", "Earns the point for identifying the Qing, Ottoman, Russian, or Austro-Hungarian Empire."],
  ["Describe one cause of the Mexican Revolution.", "Earns the point for describing unequal land distribution, Porfirio Díaz's dictatorship, foreign control of resources, or peasant demands for land reform."],
  ["Explain one reason for the collapse of the Qing dynasty.", "Earns the point for explaining foreign imperialism, internal rebellions (Taiping, Boxer), failure to modernize, and the 1911 revolution led by Sun Yat-sen."]
]],
"7.2": ["Answer the following about the causes of World War I.", [
  ["Identify one long-term cause of World War I.", "Earns the point for identifying militarism, alliances, imperialism, or nationalism (MAIN)."],
  ["Describe the immediate cause of World War I.", "Earns the point for describing the assassination of Archduke Franz Ferdinand in Sarajevo (1914) by a Serbian nationalist."],
  ["Explain how the alliance system turned a regional conflict into a world war.", "Earns the point for explaining that when Austria-Hungary declared war on Serbia, allies (Russia, Germany, France, Britain) were drawn in by their commitments."]
]],
"7.3": ["Answer the following about conducting World War I.", [
  ["Identify one new military technology used in World War I.", "Earns the point for identifying machine guns, poison gas, tanks, airplanes, submarines, or artillery."],
  ["Describe the concept of total war.", "Earns the point for describing that governments mobilized all resources (economy, industry, civilians) for the war effort, including rationing, propaganda, and conscription."],
  ["Explain why trench warfare led to such high casualties.", "Earns the point for explaining that defensive technologies (machine guns, barbed wire, artillery) made frontal attacks deadly, while offensive tactics lagged."]
]],
"7.4": ["Answer the following about the interwar economy.", [
  ["Identify one cause of the Great Depression.", "Earns the point for identifying the 1929 stock market crash, overproduction, bank failures, reduced international trade/tariffs, or war debts."],
  ["Describe how the Great Depression spread globally.", "Earns the point for describing that U.S. banks recalled loans, trade collapsed, and tariffs (e.g., Smoot-Hawley) hurt exports worldwide."],
  ["Explain one government response to the Great Depression.", "Earns the point for explaining a response such as the New Deal (Keynesian economics, public works), fascist state control of the economy, or Stalin's Five-Year Plans."]
]],
"7.5": ["Answer the following about unresolved tensions after World War I.", [
  ["Identify one provision of the Treaty of Versailles.", "Earns the point for identifying war guilt clause, reparations, German territorial losses, army limits, or League of Nations."],
  ["Describe the mandate system.", "Earns the point for describing former Ottoman and German territories placed under British or French control by the League of Nations."],
  ["Explain one way the Treaty of Versailles contributed to future conflict.", "Earns the point for explaining that harsh terms caused German resentment and economic hardship, which Hitler exploited."]
]],
"7.6": ["Answer the following about the causes of World War II.", [
  ["Identify one aggressive action taken by a fascist or militarist state before 1939.", "Earns the point for identifying Japan's invasion of Manchuria (1931) or China (1937), Italy's invasion of Ethiopia, Germany's remilitarization of the Rhineland, annexation of Austria, or Sudetenland."],
  ["Describe the policy of appeasement.", "Earns the point for describing Britain and France giving in to Hitler's demands (e.g., Munich Agreement) to avoid war."],
  ["Explain one way economic conditions contributed to the rise of fascism.", "Earns the point for explaining that the Depression caused unemployment and desperation, leading people to support leaders promising order, jobs, and national revival."]
]],
"7.7": ["Answer the following about conducting World War II.", [
  ["Identify one example of total war during World War II.", "Earns the point for identifying mobilization of women and industry, rationing, propaganda, bombing of civilians (Blitz, Dresden, Tokyo), or atomic bombs."],
  ["Describe the role of the atomic bomb in ending World War II.", "Earns the point for describing U.S. bombings of Hiroshima and Nagasaki leading to Japan's surrender in August 1945."],
  ["Explain one reason for Allied victory.", "Earns the point for explaining industrial capacity (especially U.S.), Soviet manpower, successful military campaigns, or Axis overextension."]
]],
"7.8": ["Answer the following about mass atrocities after 1900.", [
  ["Identify one genocide or mass atrocity in the twentieth century.", "Earns the point for identifying the Holocaust, Armenian Genocide, Cambodian Genocide, Rwandan Genocide, Holodomor, or others."],
  ["Describe one factor that allowed the Holocaust to occur.", "Earns the point for describing Nazi racial ideology, propaganda, dehumanization, laws (Nuremberg Laws), bureaucracy, or wartime conditions."],
  ["Explain one international response to mass atrocities.", "Earns the point for explaining the Nuremberg Trials, the UN Genocide Convention (1948), Universal Declaration of Human Rights, or international tribunals."]
]],
"7.9": ["Answer the following causation question about global conflict.", [
  ["Identify one cause of World War II that was a consequence of World War I.", "Earns the point for identifying Treaty of Versailles resentment, economic instability, weakness of the League of Nations, or rise of fascism in response to war's aftermath."],
  ["Describe one effect of the world wars on European empires.", "Earns the point for describing that the wars weakened European powers economically and militarily, making it harder to hold colonies."],
  ["Explain how World War II contributed to decolonization.", "Earns the point for explaining that colonial troops/experiences, weakened European powers, the Atlantic Charter's self-determination principle, or U.S./USSR pressure encouraged independence movements."]
]],
"8.1": ["Answer the following about setting the stage for the Cold War and decolonization.", [
  ["Identify the two superpowers after World War II.", "Earns the point for identifying the United States and the Soviet Union."],
  ["Describe one ideological difference between the superpowers.", "Earns the point for describing capitalism/democracy (U.S.) vs. communism/one-party state (USSR)."],
  ["Explain one way World War II weakened European colonial powers.", "Earns the point for explaining economic destruction, military losses, debt, or loss of prestige that made them unable to maintain colonies."]
]],
"8.2": ["Answer the following about the Cold War.", [
  ["Identify one military alliance formed during the Cold War.", "Earns the point for identifying NATO or the Warsaw Pact."],
  ["Describe the policy of containment.", "Earns the point for describing the U.S. policy of preventing the spread of communism, e.g., the Truman Doctrine, Marshall Plan, or Korean War."],
  ["Explain one example of a proxy war.", "Earns the point for explaining a conflict where superpowers supported opposing sides without directly fighting: Korea, Vietnam, Afghanistan, Angola, etc."]
]],
"8.3": ["Answer the following about the effects of the Cold War.", [
  ["Identify the Non-Aligned Movement.", "Earns the point for identifying it as a group of countries (India, Egypt, Indonesia, Yugoslavia) that refused to join either superpower bloc."],
  ["Describe one effect of the nuclear arms race.", "Earns the point for describing mutually assured destruction, the Cuban Missile Crisis, huge military spending, or arms control treaties."],
  ["Explain how the Cold War affected developing nations.", "Earns the point for explaining that superpowers supported friendly regimes, funded coups or wars, or gave aid, influencing politics in developing nations."]
]],
"8.4": ["Answer the following about the spread of communism after 1900.", [
  ["Identify one country where communists took power after 1945.", "Earns the point for identifying China, North Korea, Vietnam, Cuba, or Eastern European states."],
  ["Describe Mao Zedong's Great Leap Forward.", "Earns the point for describing an effort to rapidly industrialize and collectivize agriculture via communes and backyard furnaces, causing famine and millions of deaths."],
  ["Explain one reason communism appealed to people in colonized or developing countries.", "Earns the point for explaining that it promised land reform, equality, anti-imperialism, and an end to exploitation by foreign powers or elites."]
]],
"8.5": ["Answer the following about decolonization after 1900.", [
  ["Identify one country that gained independence through nonviolent resistance.", "Earns the point for identifying India (Gandhi), Ghana (Nkrumah), or other valid example."],
  ["Describe one method used by Gandhi to resist British rule.", "Earns the point for describing civil disobedience, the Salt March, boycotts of British goods, or noncooperation."],
  ["Explain why some colonies gained independence through armed struggle.", "Earns the point for explaining that colonial powers with many settlers or economic interests (e.g., France in Algeria, Portugal in Angola) refused to leave, so independence movements turned to armed revolt."]
]],
"8.6": ["Answer the following about newly independent states.", [
  ["Identify one challenge newly independent states faced.", "Earns the point for identifying ethnic conflict, arbitrary borders, economic dependence, weak institutions, or political instability."],
  ["Describe the partition of India in 1947.", "Earns the point for describing the division into Hindu-majority India and Muslim-majority Pakistan, causing mass migration and violence."],
  ["Explain one way a new state tried to develop its economy.", "Earns the point for explaining a policy: import substitution, nationalizing industries (e.g., Egypt's Suez Canal), state-led five-year plans, or export-oriented growth."]
]],
"8.7": ["Answer the following about global resistance to established power structures after 1900.", [
  ["Identify one nonviolent movement that challenged established power after 1900.", "Earns the point for identifying the U.S. Civil Rights Movement, anti-apartheid movement, Indian independence, or other."],
  ["Describe apartheid in South Africa.", "Earns the point for describing a system of legal racial segregation and discrimination against nonwhite South Africans (1948–1994)."],
  ["Explain one factor that led to the end of apartheid.", "Earns the point for explaining internal resistance (ANC, Mandela), international sanctions/boycotts, or economic pressure."]
]],
"8.8": ["Answer the following about the end of the Cold War.", [
  ["Identify one reform introduced by Mikhail Gorbachev.", "Earns the point for identifying glasnost (openness) or perestroika (restructuring)."],
  ["Describe one event that marked the end of the Cold War.", "Earns the point for describing the fall of the Berlin Wall (1989), revolutions in Eastern Europe, or the dissolution of the Soviet Union (1991)."],
  ["Explain one reason the Soviet Union collapsed.", "Earns the point for explaining economic stagnation, costly arms race or Afghanistan war, nationalist movements in republics, or effects of Gorbachev's reforms."]
]],
"8.9": ["Answer the following causation question about the Cold War and decolonization.", [
  ["Identify one way the Cold War influenced decolonization.", "Earns the point for identifying superpower support for independence movements, competition for influence in new nations, or pressure on European allies to decolonize."],
  ["Describe one effect of decolonization on the United Nations.", "Earns the point for describing that many new nations joined, changing its membership and priorities (e.g., the General Assembly's focus on anti-colonialism, development)."],
  ["Explain one long-term consequence of the Cold War.", "Earns the point for explaining the spread of nuclear weapons, divided states (Korea), U.S. as sole superpower, conflicts in former proxy states, or the spread of free-market economics."]
]],
"9.1": ["Answer the following about advances in technology after 1900.", [
  ["Identify one technological innovation of the twentieth century that increased global communication.", "Earns the point for identifying the radio, television, satellites, cell phones, or the internet."],
  ["Describe the Green Revolution.", "Earns the point for describing the use of high-yield seeds, chemical fertilizers, pesticides, and irrigation to increase food production, especially in Asia and Latin America."],
  ["Explain one effect of the internet on the global economy.", "Earns the point for explaining e-commerce, outsourcing of services, faster financial transactions, or global supply chains."]
]],
"9.2": ["Answer the following about disease and technology after 1900.", [
  ["Identify one disease that caused a global pandemic after 1900.", "Earns the point for identifying the 1918 influenza, HIV/AIDS, or COVID-19."],
  ["Describe one medical innovation that increased life expectancy.", "Earns the point for describing antibiotics (penicillin), vaccines (polio, smallpox), or improved sanitation."],
  ["Explain one reason some diseases remain widespread in poorer regions.", "Earns the point for explaining lack of access to health care, clean water, vaccines, or medicines, and poverty."]
]],
"9.3": ["Answer the following about debates about the environment after 1900.", [
  ["Identify one environmental problem linked to human activity after 1900.", "Earns the point for identifying climate change, deforestation, desertification, air/water pollution, or ozone depletion."],
  ["Describe one international agreement to address an environmental issue.", "Earns the point for describing the Montreal Protocol, Kyoto Protocol, or Paris Agreement."],
  ["Explain one reason environmental debates have been difficult to resolve.", "Earns the point for explaining conflicts between economic growth and environmental protection, especially between developed and developing nations."]
]],
"9.4": ["Answer the following about economics in the global age.", [
  ["Identify one example of free-market economic reform after 1970.", "Earns the point for identifying Deng Xiaoping's reforms in China, Reagan or Thatcher policies, Chile under Pinochet, or India's 1991 liberalization."],
  ["Describe one free trade agreement or organization.", "Earns the point for describing NAFTA, the WTO, the EU, or ASEAN, and what it does."],
  ["Explain one effect of globalization on workers in developed countries.", "Earns the point for explaining job losses from outsourcing, cheaper consumer goods, or growth in service jobs."]
]],
"9.5": ["Answer the following about calls for reform after 1900.", [
  ["Identify one movement for expanded rights after 1900.", "Earns the point for identifying women's suffrage, civil rights, anti-apartheid, LGBTQ+ rights, or labor movements."],
  ["Describe one example of women gaining political rights.", "Earns the point for describing women gaining the right to vote in a specific country, or other political rights."],
  ["Explain one factor that led to movements for greater equality.", "Earns the point for explaining a factor such as rising education, the UN Declaration of Human Rights, decolonization, or media awareness."]
]],
"9.6": ["Answer the following about globalized culture after 1900.", [
  ["Identify one example of global popular culture.", "Earns the point for identifying Hollywood films, K-pop, Bollywood, reggae, sports (soccer), or social media."],
  ["Describe how technology spread popular culture globally.", "Earns the point for describing radio, TV, films, internet, and streaming reaching worldwide audiences."],
  ["Explain one example of a culture adapting a global cultural trend.", "Earns the point for explaining a blend or adaptation, e.g., Bollywood blending Western film with Indian music, or local versions of fast food."]
]],
"9.7": ["Answer the following about resistance to globalization after 1900.", [
  ["Identify one group that opposed globalization.", "Earns the point for identifying anti-globalization protesters (e.g., WTO protests in Seattle 1999), labor unions, environmental groups, or nationalist movements."],
  ["Describe one criticism of globalization.", "Earns the point for describing job losses, exploitation of workers in developing countries, cultural homogenization, or environmental harm."],
  ["Explain one way a government resisted global economic or cultural influences.", "Earns the point for explaining tariffs, restrictions on foreign media, protecting local industries, or leaving trade agreements."]
]],
"9.8": ["Answer the following about institutions in a globalized world.", [
  ["Identify one international organization founded after 1945.", "Earns the point for identifying the UN, WTO, IMF, World Bank, NATO, or EU."],
  ["Describe one role of the United Nations.", "Earns the point for describing peacekeeping, human rights, humanitarian aid, or global health (WHO)."],
  ["Explain one criticism of international financial institutions such as the IMF.", "Earns the point for explaining that loan conditions (structural adjustment) required spending cuts that hurt poor populations."]
]],
"9.9": ["Answer the following about continuity and change in a globalized world.", [
  ["Identify one major change in global society since 1900.", "Earns the point for identifying a change: decolonization, rapid technological change, globalization, increased life expectancy, or expanded rights."],
  ["Describe one continuity in the global economy since 1900.", "Earns the point for describing a continuity: inequality between wealthy and poor nations, dependence on raw material exports, or the importance of trade."],
  ["Explain one cause of the change identified in part A.", "Earns the point for explaining a cause linked to the change in part A."]
]]
};
